const crypto = global.get("crypto");
const secret = env.get("LINE_CHANNEL_SECRET");
const signature = msg.req.headers["x-line-signature"];

// エラー時は後続処理を行わずHTTP応答だけ返す
function reject(statusCode, message) {
    msg.statusCode = statusCode;
    msg.payload = message;
    return [null, msg];
}

// 設定と受信データの確認
if (!secret || !crypto) {
    node.error("署名検証の設定が不足しています");
    return reject(500, "Server configuration error");
}

if (!Buffer.isBuffer(msg.payload)) {
    return reject(400, "Invalid request body");
}

// 署名がない場合は拒否
if (typeof signature !== "string" ||
    !/^[A-Za-z0-9+/]{43}=$/.test(signature)) {
    return reject(401, "Unauthorized");
}

// 受信した本文を変更せずに署名を計算
const calculated = crypto
    .createHmac("sha256", secret)
    .update(msg.payload)
    .digest();

const received = Buffer.from(signature, "base64");

// タイミング攻撃に配慮して比較
if (received.length !== calculated.length ||
    !crypto.timingSafeEqual(received, calculated)) {
    return reject(401, "Unauthorized");
}

// 署名検証が成功してからJSONを解析
try {
    msg.lineWebhook = JSON.parse(msg.payload.toString("utf8"));
} catch (err) {
    return reject(400, "Invalid JSON");
}

msg.statusCode = 200;
msg.payload = "OK";
return [msg, null];

const allowedUserId = env.get("LINE_ALLOWED_USER_ID");
const events = msg.lineWebhook?.events;

// 許可ユーザーが未設定なら処理しない
if (!allowedUserId) {
    node.error("LINE_ALLOWED_USER_IDが未設定です");
    return null;
}

if (!Array.isArray(events)) {
    return null;
}

for (const event of events) {
    // 許可したユーザーからの1対1のメッセージのみ受け付ける
    if (
        event.source?.type !== "user" ||
        event.source?.userId !== allowedUserId
    ) {
        continue;
    }

    // 「写真」の場合だけ撮影指示を生成
    if (
        event.type === "message" &&
        event.message?.type === "text" &&
        event.message.text === "写真"
    ) {
        const requestToken =
            event.webhookEventId || event.message.id;

        if (!requestToken) continue;

        node.send({
            payload: {
                command: "capture",
                requestToken
            }
        });
    }
}

return null;

const id = msg.payload?.requestToken;

if (typeof id !== "string" || !id) {
    return null;
}

const now = Date.now();
const ttl = 24 * 60 * 60 * 1000; // 24時間

// 過去に処理したイベントIDを取得
const seen = context.get("seenEventIds") || {};

// 古い履歴を削除
for (const key of Object.keys(seen)) {
    if (now - seen[key] >= ttl) {
        delete seen[key];
    }
}

// 処理済みなら撮影指示を破棄
if (Object.prototype.hasOwnProperty.call(seen, id)) {
    return null;
}

// 初回のイベントIDを記録
seen[id] = now;
context.set("seenEventIds", seen);

return msg;

const headers = msg.req.headers || {};
const crypto = global.get("crypto");
const expected = env.get("UPLOAD_API_KEY");

// 検証失敗時の応答
function reject(status, reason) {
    msg.statusCode = status;
    msg.headers = {
        "content-type": "application/json; charset=utf-8"
    };
    msg.payload = { ok: false, error: reason };
    return [null, msg];
}

// サーバー設定
if (!crypto || !expected) {
    return reject(500, "Server configuration error");
}

// デバイス認証
const received = headers["x-device-key"];

if (typeof received !== "string") {
    return reject(401, "Unauthorized");
}

const a = Buffer.from(received);
const b = Buffer.from(expected);

if (a.length !== b.length ||
    !crypto.timingSafeEqual(a, b)) {
    return reject(401, "Unauthorized");
}

// Content-Type検証
const contentType = (headers["content-type"] || "")
    .split(";")[0].trim().toLowerCase();

if (contentType !== "image/jpeg") {
    return reject(415, "Expected image/jpeg");
}

// JPEG検証
const jpeg = msg.payload;

if (!Buffer.isBuffer(jpeg)) {
    return reject(422, "Expected binary JPEG");
}


node.warn({
    requestToken: headers["x-requesttoken"],
    contentLength: headers["content-length"],
    receivedBytes: jpeg.length,
    first4: jpeg.subarray(0, 4).toString("hex"),
    last4: jpeg.subarray(-4).toString("hex")
});


if (jpeg.length > 1024 * 1024) {
    return reject(413, "Image too large");
}



// JPEG終了マーカー FF D9 の位置を探す
const eoiPos = jpeg.lastIndexOf(
    Buffer.from([0xFF, 0xD9])
);

// 終了マーカーの後ろにあるデータを確認
const trailing = eoiPos >= 0
    ? jpeg.subarray(eoiPos + 2)
    : Buffer.alloc(0);

node.warn({
    requestToken: headers["x-requesttoken"],
    receivedBytes: jpeg.length,
    eoiPosition: eoiPos,
    jpegEndBytes: eoiPos >= 0 ? eoiPos + 2 : null,
    trailingBytes: eoiPos >= 0 ? trailing.length : null,
    trailingAllFF: eoiPos >= 0
        ? trailing.every(b => b === 0xFF)
        : null
});



if (
    jpeg.length < 4 ||
    jpeg[0] !== 0xff ||
    jpeg[1] !== 0xd8 ||
    jpeg[jpeg.length - 2] !== 0xff ||
    jpeg[jpeg.length - 1] !== 0xd9
) {
    return reject(422, "Invalid JPEG markers");
}

// requestToken検証
const requestToken = headers["x-requesttoken"];

if (typeof requestToken !== "string" ||
    !/^[a-zA-Z0-9._:-]{1,128}$/.test(requestToken)) {
    return reject(400, "Invalid requestToken");
}

// ファイル名を生成
const imageId = crypto.randomUUID();

msg.filename =
    "/tmp/spresense-node-red-uploads/" + imageId + ".jpg";

// 保存結果として残す情報
msg.uploadInfo = {
    imageId,
    requestToken,
    bytes: jpeg.length,
    filename: msg.filename,
    receivedAt: new Date().toISOString()
};


node.warn("JPEG検証通過・保存先: " + msg.filename);
return [msg, null];

