const info = msg.uploadInfo;

// 保存成功のDebug情報
msg.uploadResult = {
    saved: true,
    ...info
};

// SpresenseへのHTTP応答
msg.statusCode = 201;
msg.headers = {
    "content-type": "application/json; charset=utf-8"
};

msg.payload = {
    ok: true,
    saved: true,
    imageId: info.imageId,
    requestToken: info.requestToken,
    bytes: info.bytes
};

// LINE送信用には必要な情報だけを渡す
const pushMsg = {
    uploadInfo: {
        imageId: info.imageId,
        requestToken: info.requestToken
    }
};

// 出力1：HTTP Response
// 出力2：LINE画像送信
return [msg, pushMsg];

const info = msg.uploadInfo || {};

msg.uploadResult = {
    saved: false,
    requestToken: info.requestToken || null,
    filename: info.filename || null,
    error: msg.error?.message || "Unknown storage error"
};

msg.statusCode = 500;
msg.headers = {
    "content-type": "application/json; charset=utf-8"
};

msg.payload = {
    ok: false,
    saved: false,
    error: "Storage error"
};

return msg;

const info = msg.uploadInfo;

const accessToken = env.get("LINE_CHANNEL_ACCESS_TOKEN");
const userId = env.get("LINE_ALLOWED_USER_ID");
const baseUrl = env.get("LINE_IMAGE_BASE_URL");

if (!accessToken || !userId || !baseUrl) {
    node.error("LINE configuration missing.");
    return null;
}

if (!/^https:\/\/[^/]+\/?$/.test(baseUrl)) {
    node.error("Invalid LINE_IMAGE_BASE_URL.");
    return null;
}

// 保存した画像の公開URL
const imageUrl =
    baseUrl.replace(/\/$/, "") +
    "/api/images/" +
    info.imageId +
    ".jpg";

// LINE Push APIへ送るメッセージ
return {
    method: "POST",
    url: "https://api.line.me/v2/bot/message/push",
    headers: {
        "Authorization": "Bearer " + accessToken,
        "Content-Type": "application/json"
    },
    payload: {
        to: userId,
        messages: [
            {
                type: "image",
                originalContentUrl: imageUrl,
                previewImageUrl: imageUrl
            }
        ]
    },
    imageId: info.imageId,
    requestToken: info.requestToken
};

const status = Number(msg.statusCode);

const result = {
    ok: status === 200,
    statusCode: status,
    imageId: msg.imageId,
    requestToken: msg.requestToken
};

if (status === 200) {
    node.log("LINE image push accepted.");
} else {
    node.warn("LINE image push failed: " + status);
}

// アクセストークンをDebugに出さない
return {
    payload: result
};
